create table audit_logs (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, tenant_id bigint not null, user_id bigint, entity_id varchar(64) not null, entity_type varchar(64) not null, action varchar(128) not null, after_state jsonb, before_state jsonb, primary key (id));
create table cases (risk_score_at_creation integer not null, assigned_to_id bigint, created_at timestamp(6) with time zone not null, customer_id bigint not null, id bigint generated by default as identity, related_document_id bigint, tenant_id bigint not null, updated_at timestamp(6) with time zone not null, decision varchar(32) check (decision in ('APPROVE','REJECT','ESCALATE')), status varchar(32) not null check (status in ('OPEN','UNDER_REVIEW','RESOLVED')), related_transaction_id varchar(64), decision_note TEXT, explanation TEXT not null, external_transaction_id varchar(255), primary key (id));
create table customers (dob date, face_match_score float(53), liveness_score float(53), risk_score integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, tenant_id bigint not null, kyc_status varchar(32) not null check (kyc_status in ('PENDING','VERIFIED','FLAGGED','REJECTED')), external_customer_id varchar(128), id_number varchar(512), reference_signature_url varchar(1024), name varchar(255) not null, primary key (id), constraint uk_customer_tenant_external unique (tenant_id, external_customer_id));
create table documents (fraud_risk_score float(53), signature_match_score float(53), tampering_score float(53), created_at timestamp(6) with time zone not null, customer_id bigint not null, id bigint generated by default as identity, tenant_id bigint not null, signature_match_status varchar(32) not null check (signature_match_status in ('PENDING','SCORED','SKIPPED_NO_REFERENCE')), status varchar(32) not null check (status in ('PENDING','COMPLETE','FAILED')), type varchar(32) not null check (type in ('CHEQUE','INVOICE','ID')), image_url varchar(1024), field_consistency_flags jsonb, ocr_extracted_data jsonb, primary key (id));
create table kyc_sessions (created_at timestamp(6) with time zone not null, customer_id bigint, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, tenant_id bigint not null, updated_at timestamp(6) with time zone not null, status varchar(32) not null check (status in ('PENDING','SUBMITTED','COMPLETE','FAILED')), challenge_id varchar(64) not null, public_token varchar(64) not null unique, external_customer_id varchar(128) not null, liveness_hint varchar(128), return_url varchar(1024), explanation TEXT, primary key (id));
create table refresh_tokens (revoked boolean not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null, token_hash varchar(128) not null unique, primary key (id));
create table risk_settings (anomaly_threshold float(53) not null, auto_flag_risk_score integer not null, document_weight float(53) not null, face_match_threshold float(53) not null, kyc_weight float(53) not null, signature_match_threshold float(53) not null, tampering_threshold float(53) not null, transaction_weight float(53) not null, id bigint generated by default as identity, tenant_id bigint not null unique, updated_at timestamp(6) with time zone not null, primary key (id));
create table tenant_api_keys (enabled boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, last_used_at timestamp(6) with time zone, tenant_id bigint not null, key_prefix varchar(16) not null, key_hash varchar(64) not null unique, name varchar(128) not null, primary key (id));
create table tenants (enabled boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, code varchar(64) not null unique, webhook_signing_secret varchar(256), webhook_url varchar(1024), name varchar(255) not null, primary key (id));
create table transactions (amount numeric(19,4) not null, anomaly_score float(53), available_balance numeric(19,4), flagged boolean not null, currency varchar(8) not null, customer_id bigint not null, id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, tenant_id bigint not null, recommendation varchar(32) check (recommendation in ('ALLOW','REVIEW','BLOCK')), transaction_type varchar(32), case_id varchar(64), channel varchar(64), external_transaction_id varchar(128), counterparty varchar(256), explanation TEXT, location varchar(255), rule_flags jsonb, shap_top_features jsonb, primary key (id), constraint uq_transactions_tenant_external unique (tenant_id, external_transaction_id));
create table users (enabled boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, tenant_id bigint not null, role varchar(32) not null check (role in ('ADMIN','COMPLIANCE','ANALYST')), username varchar(64) not null, password_hash varchar(255) not null, primary key (id), unique (tenant_id, username));
create table webhook_deliveries (attempts integer not null, created_at timestamp(6) with time zone not null, delivered_at timestamp(6) with time zone, id bigint generated by default as identity, next_attempt_at timestamp(6) with time zone not null, tenant_id bigint not null, event_id varchar(64) not null unique, payload TEXT not null, primary key (id));
